// Derived from the user-supplied Meshy snail. See provenance.json.
let data;
const packed='';
export function modelGeometryData(){
 if(!data){const s=atob(packed),bytes=new Uint8Array(s.length);for(let i=0;i<s.length;i++)bytes[i]=s.charCodeAt(i);const b=bytes.buffer;data={
  positions:new Float32Array(b,0,78501),
  normals:new Float32Array(b,314004,78501),
  uvs:new Float32Array(b,628008,52334),
  indices:new Uint16Array(b,837344,108000),
 };}
 return data;
}
